// context-packet.js — bounded evidence packer (Node.js builtins only).
//
// Exports the synchronous packContext(sections, maxBytes) API and a CLI:
//   node context-packet.js INPUT_JSON_FILE
//
// The CLI reads a UTF-8 JSON file containing {sections, maxBytes} (extra
// fields ignored), prints exactly one result JSON line on success, and exits
// 2 with a diagnostic on stderr (and no stdout) for any invalid input.

import {readFileSync, realpathSync} from 'node:fs';
import {fileURLToPath} from 'node:url';

const isNonNegativeSafeInteger = (value) =>
  typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;

// Exact serialized frame for one section; indivisible.
const frameFor = (section) =>
  '### ' + JSON.stringify(section.id) + '\n' + section.text + '\n';

// Validate the entire input before any packing happens. Never mutates input.
function assertValidInput(sections, maxBytes) {
  if (!isNonNegativeSafeInteger(maxBytes)) {
    throw new Error('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) {
    throw new Error('sections must be an array');
  }
  const seen = new Set();
  for (let i = 0; i < sections.length; i++) {
    if (!(i in sections)) {
      throw new Error(`sections must be a dense array; missing slot at index ${i}`);
    }
    const section = sections[i];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
      throw new Error(`sections[${i}] must be a non-null, non-array object`);
    }
    if (typeof section.id !== 'string' || section.id.length === 0) {
      throw new Error(`sections[${i}].id must be a nonempty string`);
    }
    if (typeof section.text !== 'string') {
      throw new Error(`sections[${i}].text must be a string`);
    }
    if (!isNonNegativeSafeInteger(section.priority)) {
      throw new Error(`sections[${i}].priority must be a nonnegative safe integer`);
    }
    if (typeof section.required !== 'boolean') {
      throw new Error(`sections[${i}].required must be a boolean`);
    }
    if (seen.has(section.id)) {
      throw new Error(`duplicate section id: ${JSON.stringify(section.id)}`);
    }
    seen.add(section.id);
  }
}

export function packContext(sections, maxBytes) {
  // Full validation first, even when the budget is zero or a section would be
  // omitted by the budget.
  assertValidInput(sections, maxBytes);

  const items = new Array(sections.length);
  for (let i = 0; i < sections.length; i++) {
    const section = sections[i];
    const frame = frameFor(section);
    items[i] = {
      index: i,
      id: section.id,
      priority: section.priority,
      required: section.required,
      frame,
      cost: Buffer.byteLength(frame, 'utf8'),
    };
  }

  // 1. All required sections first, in original input order (priority
  //    ignored). Throw rather than return a partial required set.
  const includedItems = [];
  let remaining = maxBytes;
  for (const item of items) {
    if (!item.required) continue;
    if (item.cost > remaining) {
      throw new Error('required sections exceed the maxBytes budget');
    }
    remaining -= item.cost;
    includedItems.push(item);
  }

  // 2. Optional sections by descending priority, ties by original input
  //    order. Include when the whole frame fits; otherwise skip and keep
  //    trying later sections.
  const optional = items.filter((item) => !item.required);
  optional.sort((a, b) => b.priority - a.priority || a.index - b.index);
  const includedIds = new Set(includedItems.map((item) => item.id));
  for (const item of optional) {
    if (item.cost <= remaining) {
      remaining -= item.cost;
      includedItems.push(item);
      includedIds.add(item.id);
    }
  }

  // 3. Output in inclusion order; omitted optional IDs in original input
  //    order.
  const parts = new Array(includedItems.length);
  let bytes = 0;
  for (let i = 0; i < includedItems.length; i++) {
    parts[i] = includedItems[i].frame;
    bytes += includedItems[i].cost;
  }
  const omitted = [];
  for (const item of items) {
    if (!item.required && !includedIds.has(item.id)) omitted.push(item.id);
  }

  return {
    text: parts.join(''),
    bytes,
    included: includedItems.map((item) => item.id),
    omitted,
  };
}

// --- CLI (runs only when executed directly, never on import) ---

function fail(message) {
  process.stderr.write(`context-packet: ${message}\n`);
  process.exitCode = 2;
}

function runCli(argv) {
  if (argv.length !== 1) {
    fail('exactly one argument is required: INPUT_JSON_FILE');
    return;
  }
  const file = argv[0];

  let raw;
  try {
    raw = readFileSync(file, 'utf8');
  } catch (err) {
    fail(`cannot read ${file}: ${err.message}`);
    return;
  }

  let doc;
  try {
    doc = JSON.parse(raw);
  } catch (err) {
    fail(`invalid JSON in ${file}: ${err.message}`);
    return;
  }
  if (doc === null || typeof doc !== 'object' || Array.isArray(doc)) {
    fail(`input JSON must be an object with "sections" and "maxBytes"`);
    return;
  }

  try {
    const result = packContext(doc.sections, doc.maxBytes);
    process.stdout.write(JSON.stringify(result) + '\n');
  } catch (err) {
    fail(err.message);
  }
}

const isDirectRun = (() => {
  try {
    return (
      process.argv[1] !== undefined &&
      realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url))
    );
  } catch {
    return false;
  }
})();

if (isDirectRun) {
  runCli(process.argv.slice(2));
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {packContext} from '../context-packet.js';

const CLI = fileURLToPath(new URL('../context-packet.js', import.meta.url));
const section = (id, text, priority = 0, required = false) => ({id, text, priority, required});
const frame = (id, text) => `### ${JSON.stringify(id)}\n${text}\n`;
const cost = (id, text) => Buffer.byteLength(frame(id, text), 'utf8');
const throws = (fn) => assert.throws(fn, Error);

test('return value has exactly the documented shape', () => {
  const result = packContext([section('a', 'x')], 100);
  assert.deepEqual(Object.keys(result), ['text', 'bytes', 'included', 'omitted']);
});

test('exact frame format and UTF-8 byte costs', () => {
  const sections = [section('雪', 'é\u{1F600}\u0000', 0)];
  const result = packContext(sections, 1000);
  assert.equal(result.text, frame('雪', 'é\u{1F600}\u0000'));
  assert.equal(result.bytes, Buffer.byteLength(frame('雪', 'é\u{1F600}\u0000'), 'utf8'));
  assert.deepEqual(result.included, ['雪']);
  assert.deepEqual(result.omitted, []);
});

test('empty input returns empty result for any valid budget', () => {
  for (const maxBytes of [0, 1, Number.MAX_SAFE_INTEGER]) {
    assert.deepEqual(packContext([], maxBytes), {text: '', bytes: 0, included: [], omitted: []});
  }
});

test('required sections come first, in input order, ignoring priority', () => {
  const sections = [
    section('req-low', 'a', 1, true),
    section('opt-high', 'b', 99),
    section('req-high', 'c', 90, true),
    section('opt-low', 'd', 2),
  ];
  const result = packContext(sections, 1000);
  assert.deepEqual(result.included, ['req-low', 'req-high', 'opt-high', 'opt-low']);
  assert.deepEqual(result.omitted, []);
  assert.equal(
    result.text,
    frame('req-low', 'a') + frame('req-high', 'c') + frame('opt-high', 'b') + frame('opt-low', 'd'),
  );
});

test('required overflow throws; exact required fit is allowed', () => {
  const total = cost('r1', 'x') + cost('r2', 'y');
  assert.deepEqual(
    packContext([section('r1', 'x', 0, true), section('r2', 'y', 0, true)], total),
    {text: frame('r1', 'x') + frame('r2', 'y'), bytes: total, included: ['r1', 'r2'], omitted: []},
  );
  throws(() => packContext([section('r1', 'x', 0, true), section('r2', 'y', 0, true)], total - 1));
  throws(() => packContext([section('r1', 'x', 0, true)], 0));
  // Validation runs before packing: invalid section AND overflow -> validation error.
  throws(() => packContext([section('', 'x', 0, true), section('r', 'y', 0, true)], 0));
});

test('optional: descending priority, ties by input order, skip instead of stop', () => {
  const big = section('big', 'z'.repeat(50), 10);
  const mid = section('mid', 'm', 5);
  const low = section('low', 'l', 5);
  const small = section('small', 's', 1);
  const sections = [big, low, mid, small];
  const budget = cost('mid', 'm') + cost('low', 'l') + cost('small', 's');
  const result = packContext(sections, budget);
  assert.deepEqual(result.included, ['mid', 'low', 'small']);
  assert.deepEqual(result.omitted, ['big']); // original input order, not priority order
  assert.equal(result.text, frame('mid', 'm') + frame('low', 'l') + frame('small', 's'));
  assert.equal(result.bytes, budget);
  assert.equal(result.bytes, Buffer.byteLength(result.text, 'utf8'));
});

test('exact optional fits are included and the remainder keeps flowing', () => {
  const a = section('a', 'x', 3);
  const b = section('b', 'y', 2);
  const c = section('c', 'z', 1);
  const budget = cost('a', 'x') + cost('b', 'y') + cost('c', 'z');
  const result = packContext([c, a, b], budget);
  assert.deepEqual(result.included, ['a', 'b', 'c']);
  assert.deepEqual(result.omitted, []);
});

test('zero budget omits all optionals and keeps empty frames out', () => {
  const result = packContext([section('a', 'x', 5), section('b', 'y', 1)], 0);
  assert.deepEqual(result, {text: '', bytes: 0, included: [], omitted: ['a', 'b']});
});

test('unknown object fields are ignored; no input mutation', () => {
  const noisy = {id: 'a', text: 't', priority: 0, required: false, junk: [1, {x: 2}], extra: 7};
  const result = packContext([noisy], 100);
  assert.deepEqual(result.included, ['a']);
  assert.equal(noisy.text, 't');
  assert.deepEqual(noisy, {id: 'a', text: 't', priority: 0, required: false, junk: [1, {x: 2}], extra: 7});
  const input = [section('b', 'b', 1), section('a', 'a', 1)];
  const before = JSON.stringify(input);
  packContext(input, 100);
  assert.equal(JSON.stringify(input), before);
});

test('validation: maxBytes', () => {
  const bad = [-1, -0.5, 0.5, NaN, Infinity, -Infinity, '0', '5', true, false, null, undefined, {},
    Number.MAX_SAFE_INTEGER + 1, Number.MIN_SAFE_INTEGER];
  for (const value of bad) throws(() => packContext([], value));
  // valid extremes
  assert.deepEqual(packContext([], 0), {text: '', bytes: 0, included: [], omitted: []});
  assert.deepEqual(packContext([], Number.MAX_SAFE_INTEGER), {text: '', bytes: 0, included: [], omitted: []});
});

test('validation: sections container', () => {
  for (const value of [null, undefined, 5, 's', true, {}, new Set(), new Map()]) {
    throws(() => packContext(value, 10));
  }
  const holeStart = new Array(1); // [hole]
  const holeMiddle = [section('a', 'x'), undefined, section('b', 'x')].map((s) => s);
  const sparseEnd = [];
  sparseEnd[2] = section('a', 'x');
  const denseWithUndefined = [section('a', 'x'), undefined];
  for (const value of [holeStart, holeMiddle, sparseEnd, denseWithUndefined]) {
    throws(() => packContext(value, 10));
  }
});

test('validation: section entry type and fields', () => {
  for (const entry of [null, 5, 's', true, undefined, [], new Map()]) {
    throws(() => packContext([entry], 10));
  }
  throws(() => packContext([{}], 10));
  throws(() => packContext([section('', 'x')], 10)); // empty id
  for (const id of [0, 1.5, null, undefined, [], {}, true]) {
    throws(() => packContext([section(id, 'x')], 10));
  }
  for (const text of [0, null, undefined, [], true]) {
    throws(() => packContext([section('a', text)], 10));
  }
  assert.doesNotThrow(() => packContext([section('a', '')], 10)); // empty text is fine
  for (const priority of [-1, 0.5, NaN, Infinity, '0', null, undefined, Number.MAX_SAFE_INTEGER + 1]) {
    throws(() => packContext([section('a', 'x', priority)], 10));
  }
  for (const required of [0, 1, 'true', 'false', null, undefined]) {
    throws(() => packContext([section('a', 'x', 0, required)], 10));
  }
  assert.doesNotThrow(() => packContext([section('a', 'x', Number.MAX_SAFE_INTEGER, false)], 10));
});

test('validation: duplicate and exotic IDs', () => {
  throws(() => packContext([section('a', 'x'), section('a', 'y')], 1000));
  throws(() => packContext([section('A', 'x', 0), section('a', 'y', 0)], 1000).included.length === 1 || Promise.resolve(), null);
  // Case-sensitive IDs are distinct and both valid.
  assert.deepEqual(packContext([section('A', 'x'), section('a', 'y')], 1000).included, ['A', 'a']);
  // Weird-but-valid IDs: spaces, unicode, newlines, NUL, __proto__.
  const exotic = [' spaced id ', 'uni\u00e9\u96ea', 'line1\nline2', '\u0000', '__proto__', 'constructor', 'hasOwnProperty'];
  const ids = new Set(exotic);
  assert.equal(ids.size, exotic.length);
  const result = packContext(exotic.map((id) => section(id, 't')), 10000);
  assert.deepEqual(result.included, exotic);
  for (const id of exotic) assert.ok(result.text.includes(`### ${JSON.stringify(id)}\n`));
});

test('importing the module did not run the CLI', () => {
  assert.ok(process.exitCode === null || process.exitCode === 0);
});

test('CLI behavior', (t) => {
  const dir = mkdtempSync(join(tmpdir(), 'context-packet-'));
  t.after(() => rmSync(dir, {recursive: true, force: true}));
  const write = (name, content) => {
    const file = join(dir, name);
    writeFileSync(file, content, 'utf8');
    return file;
  };
  const run = (args) => {
    const r = spawnSync(process.execPath, [CLI, ...args], {encoding: 'utf8'});
    return {code: r.status, stdout: r.stdout ?? '', stderr: r.stderr ?? ''};
  };
  const failExpect = (r) => {
    assert.equal(r.code, 2);
    assert.equal(r.stdout, '');
    assert.ok(r.stderr.length > 0);
  };

  const doc = {
    sections: [section('big', 'z'.repeat(50), 10), section('a', 'x', 3), section('b', 'y', 2), section('r', 'keep', 0, true)],
    maxBytes: 300,
    ignoredExtraField: {nested: true},
  };
  const expected = packContext(doc.sections, doc.maxBytes);

  // success: one JSON line + newline, exit 0, no stderr, extra fields ignored
  const ok = run([write('ok.json', JSON.stringify(doc))]);
  assert.equal(ok.code, 0);
  assert.equal(ok.stderr, '');
  assert.equal(ok.stdout, JSON.stringify(expected) + '\n');
  assert.deepEqual(JSON.parse(ok.stdout), expected);

  // Unicode survives the round trip.
  const uniDoc = {sections: [section('雪', 'é'), section('uni req', '你好', 0, true)], maxBytes: 500};
  const uni = run([write('uni.json', JSON.stringify(uniDoc))]);
  assert.equal(uni.code, 0);
  assert.deepEqual(JSON.parse(uni.stdout), packContext(uniDoc.sections, uniDoc.maxBytes));

  // arg-count and file failures
  failExpect(run([]));
  failExpect(run(['a.json', 'b.json']));
  failExpect(run([join(dir, 'missing.json')]));

  // unreadable file: a directory is not readable as a file
  failExpect(run([dir]));

  // invalid JSON
  failExpect(run([write('bad-json.json', '{nope')]));
  failExpect(run([write('empty.json', '')]));

  // invalid API input
  failExpect(run([write('dup.json', JSON.stringify({sections: [section('a', 'x'), section('a', 'y')], maxBytes: 100})))]));
  failExpect(run([write('sparse.json', JSON.stringify({sections: [section('a', 'x'), null, section('b', 'x')], maxBytes: 100})))]));
  failExpect(run([write('noid.json', JSON.stringify({sections: [{text: 'x', priority: 0, required: false}], maxBytes: 100})))]));
  failExpect(run([write('badprio.json', JSON.stringify({sections: [section('a', 'x', -1)], maxBytes: 100})))]));
  failExpect(run([write('badreq.json', JSON.stringify({sections: [section('a', 'x', 0, 'yes')], maxBytes: 100})))]));
  failExpect(run([write('badmax.json', JSON.stringify({sections: [], maxBytes: -5})))]));
  failExpect(run([write('nomax.json', JSON.stringify({sections: []})))]));
  failExpect(run([write('nosec.json', JSON.stringify({maxBytes: 10})))]));

  // top-level document not an object
  failExpect(run([write('arr.json', JSON.stringify([]))]));
  failExpect(run([write('null.json', 'null')]));
  failExpect(run([write('str.json', '"hello"')]));

  // required overflow
  const overflow = {sections: [section('r1', 'x', 0, true), section('r2', 'y', 0, true)], maxBytes: 10};
  failExpect(run([write('overflow.json', JSON.stringify(overflow))]));

  // success on an exact fit
  const exact = {sections: [section('r', 'x', 0, true)], maxBytes: cost('r', 'x')};
  const exactRun = run([write('exact.json', JSON.stringify(exact))]);
  assert.equal(exactRun.code, 0);
  assert.deepEqual(JSON.parse(exactRun.stdout), {text: frame('r', 'x'), bytes: cost('r', 'x'), included: ['r'], omitted: []});
});

