// context-packet.js — bounded evidence packer (Node.js builtins only).
//
// Exports the synchronous packContext(sections, maxBytes) API and a CLI:
//   node context-packet.js INPUT_JSON_FILE
//
// The CLI reads a UTF-8 JSON file containing {sections, maxBytes} (extra
// fields ignored), prints exactly one result JSON line on success, and exits
// 2 with a diagnostic on stderr (and no stdout) for any invalid input.

import {readFileSync, realpathSync} from 'node:fs';
import {fileURLToPath} from 'node:url';

const isNonNegativeSafeInteger = (value) =>
  typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;

// Exact serialized frame for one section; indivisible.
const frameFor = (section) =>
  '### ' + JSON.stringify(section.id) + '\n' + section.text + '\n';

// Validate the entire input before any packing happens. Never mutates input.
function assertValidInput(sections, maxBytes) {
  if (!isNonNegativeSafeInteger(maxBytes)) {
    throw new Error('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) {
    throw new Error('sections must be an array');
  }
  const seen = new Set();
  for (let i = 0; i < sections.length; i++) {
    if (!(i in sections)) {
      throw new Error(`sections must be a dense array; missing slot at index ${i}`);
    }
    const section = sections[i];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
      throw new Error(`sections[${i}] must be a non-null, non-array object`);
    }
    if (typeof section.id !== 'string' || section.id.length === 0) {
      throw new Error(`sections[${i}].id must be a nonempty string`);
    }
    if (typeof section.text !== 'string') {
      throw new Error(`sections[${i}].text must be a string`);
    }
    if (!isNonNegativeSafeInteger(section.priority)) {
      throw new Error(`sections[${i}].priority must be a nonnegative safe integer`);
    }
    if (typeof section.required !== 'boolean') {
      throw new Error(`sections[${i}].required must be a boolean`);
    }
    if (seen.has(section.id)) {
      throw new Error(`duplicate section id: ${JSON.stringify(section.id)}`);
    }
    seen.add(section.id);
  }
}

export function packContext(sections, maxBytes) {
  // Full validation first, even when the budget is zero or a section would be
  // omitted by the budget.
  assertValidInput(sections, maxBytes);

  const items = new Array(sections.length);
  for (let i = 0; i < sections.length; i++) {
    const section = sections[i];
    const frame = frameFor(section);
    items[i] = {
      index: i,
      id: section.id,
      priority: section.priority,
      required: section.required,
      frame,
      cost: Buffer.byteLength(frame, 'utf8'),
    };
  }

  // 1. All required sections first, in original input order (priority
  //    ignored). Throw rather than return a partial required set.
  const includedItems = [];
  let remaining = maxBytes;
  for (const item of items) {
    if (!item.required) continue;
    if (item.cost > remaining) {
      throw new Error('required sections exceed the maxBytes budget');
    }
    remaining -= item.cost;
    includedItems.push(item);
  }

  // 2. Optional sections by descending priority, ties by original input
  //    order. Include when the whole frame fits; otherwise skip and keep
  //    trying later sections.
  const optional = items.filter((item) => !item.required);
  optional.sort((a, b) => b.priority - a.priority || a.index - b.index);
  const includedIds = new Set(includedItems.map((item) => item.id));
  for (const item of optional) {
    if (item.cost <= remaining) {
      remaining -= item.cost;
      includedItems.push(item);
      includedIds.add(item.id);
    }
  }

  // 3. Output in inclusion order; omitted optional IDs in original input
  //    order.
  const parts = new Array(includedItems.length);
  let bytes = 0;
  for (let i = 0; i < includedItems.length; i++) {
    parts[i] = includedItems[i].frame;
    bytes += includedItems[i].cost;
  }
  const omitted = [];
  for (const item of items) {
    if (!item.required && !includedIds.has(item.id)) omitted.push(item.id);
  }

  return {
    text: parts.join(''),
    bytes,
    included: includedItems.map((item) => item.id),
    omitted,
  };
}

// --- CLI (runs only when executed directly, never on import) ---

function fail(message) {
  process.stderr.write(`context-packet: ${message}\n`);
  process.exitCode = 2;
}

function runCli(argv) {
  if (argv.length !== 1) {
    fail('exactly one argument is required: INPUT_JSON_FILE');
    return;
  }
  const file = argv[0];

  let raw;
  try {
    raw = readFileSync(file, 'utf8');
  } catch (err) {
    fail(`cannot read ${file}: ${err.message}`);
    return;
  }

  let doc;
  try {
    doc = JSON.parse(raw);
  } catch (err) {
    fail(`invalid JSON in ${file}: ${err.message}`);
    return;
  }
  if (doc === null || typeof doc !== 'object' || Array.isArray(doc)) {
    fail(`input JSON must be an object with "sections" and "maxBytes"`);
    return;
  }

  try {
    const result = packContext(doc.sections, doc.maxBytes);
    process.stdout.write(JSON.stringify(result) + '\n');
  } catch (err) {
    fail(err.message);
  }
}

const isDirectRun = (() => {
  try {
    return (
      process.argv[1] !== undefined &&
      realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url))
    );
  } catch {
    return false;
  }
})();

if (isDirectRun) {
  runCli(process.argv.slice(2));
}

